import React, { Component } from 'react'
//import { connect } from 'react-redux';
import Form from 'react-bootstrap/Form'
import Button from 'react-bootstrap/Button'
import Modal from 'react-bootstrap/Modal'

import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'
import { library } from '@fortawesome/fontawesome-svg-core'
import { faCog } from '@fortawesome/free-solid-svg-icons'
library.add(faCog)

class ConfigModal extends Component {
    
    handleChange = (event) => {
          
        this.props.handleTestModeChange(event)
        
    }
    
    handleCheckClick = () => {
        this.setState({ checked: !this.state.checked });
      }
    
    render() {
        
        const isTestMode = this.props.isTestMode ? "checked" : "";
                                 
        return (
                               
        <Modal show={this.props.showConfigModal} onHide={this.props.handleCloseConfigModal}>
          <Modal.Header closeButton>
            <Modal.Title>Options</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Form.Group controlId="formBasicCheckbox">
            <Form.Check
            type="checkbox"
            label="Test Mode (do not actually send messages)"
checked={this.state.checked} onChange={this.handleCheckClick}
            />
          </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="primary" onClick={this.props.handleCloseConfigModal}>
              Save & Close
            </Button>
          </Modal.Footer>
        </Modal>

            
        );
    }

}

export default ConfigModal;
